// Récupère les données envoyées par React.
const body = $input.first().json.body || $input.first().json

// Récupère l'expéditeur du mail.
const expediteur = body.expediteur

// Récupère l'objet du mail.
const objet = body.objet

// Récupère le contenu du mail.
const contenu = body.contenu

// Vérifie si l'expéditeur est absent.
if (!expediteur) {
  // Arrête le workflow avec une erreur claire.
  throw new Error('Expéditeur manquant.')
}

// Vérifie si l'objet est absent.
if (!objet) {
  // Arrête le workflow avec une erreur claire.
  throw new Error('Objet du mail manquant.')
}

// Vérifie si le contenu est absent.
if (!contenu) {
  // Arrête le workflow avec une erreur claire.
  throw new Error('Contenu du mail manquant.')
}

// Retourne les données propres au nœud suivant.
return [
  {
    json: {
      expediteur: expediteur,
      objet: objet,
      contenu: contenu
    }
  }
]

// Récupère les données du mail.
const mail = $input.first().json

// Prépare la consigne envoyée à Groq.
const prompt = `
Tu dois rédiger une proposition de réponse à un e-mail.

Contexte du mail reçu :
Expéditeur : ${mail.expediteur}
Objet : ${mail.objet}
Contenu :
${mail.contenu}

Consignes :
- Réponds uniquement avec le texte de l'e-mail à envoyer.
- Écris en français simple, clair et professionnel.
- Sois poli et naturel.
- Ne mets pas de titre comme "Objet" ou "Réponse".
- Ne mets pas de Markdown.
- Ne mets pas d'astérisques.
- Ne promets rien qui n'est pas dans le message reçu.
- Termine par une formule simple de politesse.
`

// Retourne le prompt pour Groq.
return [
  {
    json: {
      expediteur: mail.expediteur,
      objet: mail.objet,
      contenu: mail.contenu,
      prompt: prompt
    }
  }
]

// Récupère la réponse générée par Groq.
const aiResponse = $input.first().json

// Essaie de récupérer le texte généré dans plusieurs champs possibles.
const generatedReply =
  aiResponse.text ||
  aiResponse.output ||
  aiResponse.response ||
  aiResponse.result ||
  aiResponse.content ||
  aiResponse.answer ||
  aiResponse.message ||
  ''

// Nettoie la réponse générée.
const cleanReply = generatedReply.trim()

// Vérifie si Groq a généré une réponse.
if (!cleanReply) {
  // Arrête le workflow avec une erreur claire.
  throw new Error('Groq n’a pas généré de réponse.')
}

// Retourne la réponse finale vers React.
return [
  {
    json: {
      success: true,
      reply: cleanReply,
      message: 'Réponse IA générée avec succès.'
    }
  }
]
